using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9: default discriminator property renamed from "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator", and direct SQL queries reference c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9: id no longer includes the discriminator (was "Product|123", now "123").
            // Existing documents have the compound format; preserve it so point-reads still work.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // REMOVED: HasIndex — EF Core 9 Cosmos provider throws at startup.
        // Manage indexing via the container's indexing policy in Azure Portal / Bicep / Terraform.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

